problems.solution:
def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

tests.src:
for n in range(10):
    want = 1
    for k in range(1, n + 1):
        want *= k
    assert factorial(n) == want, (n, factorial(n), want)

problems.solution:
def sum_list(values):
    if not values:
        return 0
    return values[0] + sum_list(values[1:])

def max_of_list(values):
    if len(values) == 1:
        return values[0]
    rest_max = max_of_list(values[1:])
    return values[0] if values[0] > rest_max else rest_max

def count_value(nested, target):
    total = 0
    for item in nested:
        if isinstance(item, list):
            total += count_value(item, target)
        elif item == target:
            total += 1
    return total

tests.src:
import random
random.seed(5)

def make(depth):
    if depth == 0 or random.random() < 0.4:
        return random.randint(0, 4)
    return [make(depth - 1) for _ in range(random.randint(0, 3))]

def flat(nested):
    out = []
    for item in nested:
        if isinstance(item, list):
            out += flat(item)
        else:
            out.append(item)
    return out

for _ in range(100):
    tree = [make(3) for _ in range(random.randint(0, 4))]
    for target in range(5):
        want = flat(tree).count(target)
        assert count_value(tree, target) == want, (tree, target)

problems.solution:
def flatten(nested):
    for item in nested:
        if isinstance(item, list):
            yield from flatten(item)
        else:
            yield item

