problems.solution:
def index_of_max(values):

    def best(values):
        if len(values) == 1:
            return values[0], 0
        rest_value, rest_index = best(values[1:])
        if values[0] >= rest_value:
            return values[0], 0
        return rest_value, rest_index + 1

    return best(values)[1]

